#!/usr/bin/env bash
# Build LightFM into the active backend virtualenv.
# Why a script: LightFM has no Linux wheels, PyPI 1.17's setup fails on current setuptools, and the
# C files shipped in the repo were generated by an old Cython that doesn't compile on Python 3.12.
# So we build a pinned upstream commit and regenerate those C files with Cython 0.29 first.
# Needs a C compiler: sudo apt install -y build-essential python3-dev
set -euo pipefail

LIGHTFM_COMMIT=0c9c31e027b976beab2385e268b58010fff46096   # lyst/lightfm master, reports version 1.17
PYTHON="${PYTHON:-$(dirname "$0")/../.venv/bin/python}"

command -v cc >/dev/null || { echo "No C compiler found. Run: sudo apt install -y build-essential python3-dev" >&2; exit 1; }
[ -x "$PYTHON" ] || { echo "Python not found at $PYTHON (create backend/.venv first or set PYTHON=...)" >&2; exit 1; }

if command -v uv >/dev/null; then pip_install() { uv pip install --python "$PYTHON" "$@"; }
else pip_install() { "$PYTHON" -m pip install "$@"; }; fi

src="$(mktemp -d)"; trap 'rm -rf "$src"' EXIT
git clone --quiet https://github.com/lyst/lightfm "$src"
git -C "$src" checkout --quiet "$LIGHTFM_COMMIT"

pip_install "setuptools<70" wheel "cython>=0.29.37,<3" numpy scipy
(cd "$src" && "$PYTHON" setup.py -q cythonize)
pip_install --no-build-isolation "$src"

"$PYTHON" -c "import lightfm; print('LightFM', lightfm.__version__, 'installed')"
